import sys

def solve():
 data=list(map(int,sys.stdin.buffer.read().split())); n=data[0]; arr=data[1:]
 primes={}
 for i,a in enumerate(arr):
  x=a; q=2
  while q*q<=x:
   if x%q==0:
    e=0
    while x%q==0:x//=q;e+=1
    primes.setdefault(q,[0]*(n-1))[i]=e
   q+=1
  if x>1: primes.setdefault(x,[0]*(n-1))[i]=1
 ans=1
 for p,es in primes.items():
  pw=[1]*(max(sum(es),max(es)*n)+1)
  for k in range(1,len(pw)): pw[k]=pw[k-1]*p%MOD
  dp={0:1}; seen=1
  for e in es:
   if e==0:
    dp={d:v*pw[d]%MOD for d,v in dp.items()}
   else:
    nd={}
    for d,v in dp.items():
     y=d+e
     nd[y]=(nd.get(y,0)+v*pw[y])%MOD
     y=d-e
     if y>=0: nd[y]=(nd.get(y,0)+v*pw[y])%MOD
     else: nd[0]=(nd.get(0,0)+v*pw[(-y)*seen])%MOD
    dp=nd
   seen+=1
  ans=ans*sum(dp.values())%MOD
 print(ans)
solve()

