import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    a = data[1:]
    V = 100000

    phi = list(range(V + 1))
    for p in range(2, V + 1):
        if phi[p] == p:
            for x in range(p, V + 1, p):
                phi[x] -= phi[x] // p

    spf = list(range(V + 1))
    for p in range(2, int(V ** 0.5) + 1):
        if spf[p] == p:
            for x in range(p * p, V + 1, p):
                if spf[x] == x:
                    spf[x] = p

    agg = [0] * (V + 1)
    ans = 0
    weight = 1
    out = []
    for x in a:
        y = x
        factors = []
        while y > 1:
            p = spf[y]
            e = 0
            while y % p == 0:
                y //= p
                e += 1
            factors.append((p, e))

        divs = [1]
        for p, e in factors:
            old = divs[:]
            power = 1
            for _ in range(e):
                power *= p
                divs.extend(d * power for d in old)

        s = 0
        for d in divs:
            s += phi[d] * agg[d]
        ans = (2 * ans + s) % MOD
        out.append(str(ans))
        for d in divs:
            agg[d] = (agg[d] + weight) % MOD
        weight = weight * 2 % MOD

    sys.stdout.write('\n'.join(out))

if __name__ == '__main__':
    main()

