from math import comb
class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)
        ways = [[0] * (n + 1) for _ in range(n + 1)]
        for i in range(n + 1):
            ways[i][0] = ways[i][i] = 1
            for j in range(1, i):
                ways[i][j] = (ways[i-1][j-1] + ways[i-1][j]) % MOD
        ans = 0
        for t in range(1, n + 1):
            x = t
            steps = 0
            while x != 1:
                x = x.bit_count()
                steps += 1
            if steps + 1 > k:
                continue
            used = 0
            cnt = 0
            for i, ch in enumerate(s):
                if ch == '1':
                    rem = n - i - 1
                    need = t - used
                    if 0 <= need <= rem:
                        cnt += ways[rem][need]
                    used += 1
            ans += cnt
        return ans % MOD

