from typing import List
from functools import lru_cache
import sys

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid)
        m = len(grid[0])
        sys.setrecursionlimit(10000)

        # Clockwise order: southeast, southwest, northwest, northeast.
        dr = (1, 1, -1, -1)
        dc = (1, -1, -1, 1)

        @lru_cache(None)
        def extend(r: int, c: int, d: int, expected: int, can_turn: bool) -> int:
            if not (0 <= r < n and 0 <= c < m) or grid[r][c] != expected:
                return 0

            next_value = 0 if expected == 2 else 2
            nr = r + dr[d]
            nc = c + dc[d]
            best = extend(nr, nc, d, next_value, can_turn)

            if can_turn:
                nd = (d + 1) % 4
                best = max(best, extend(r + dr[nd], c + dc[nd], nd,
                                        next_value, False))
            return 1 + best

        answer = 0
        for r in range(n):
            for c in range(m):
                if grid[r][c] == 1:
                    answer = max(answer, 1)
                    for d in range(4):
                        answer = max(answer, 1 + extend(r + dr[d], c + dc[d], d, 2, True))
        return answer

