from typing import List
from math import factorial

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odds = (n + 1) // 2
        evens = n // 2
        total = factorial(odds) * factorial(evens) * (2 if n % 2 == 0 else 1)
        if k > total:
            return []
        unused = set(range(1, n + 1))
        ans = []
        next_parity = None
        for pos in range(n):
            candidates = sorted(x for x in unused if next_parity is None or x % 2 == next_parity)
            chosen = None
            for x in candidates:
                ro = sum(y % 2 for y in unused) - (x % 2)
                re = len(unused) - sum(y % 2 for y in unused) - (1 - x % 2)
                block = factorial(ro) * factorial(re)
                if k > block:
                    k -= block
                else:
                    chosen = x
                    break
            if chosen is None:
                return []
            ans.append(chosen)
            unused.remove(chosen)
            if next_parity is None:
                next_parity = 2 - chosen % 2 # odd 1 -> 1? wrong formula
            else:
                next_parity = 1 - next_parity
        return ans

