class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        coeff = []
        for i in range(m):
            j = n - 1 - i
            if i == j:
                c = pow(10, i, k)
            else:
                c = (pow(10, i, k) + pow(10, j, k)) % k
            coeff.append(c)
        # suffix[t][r]: residue r can be formed by positions t..m-1
        suffix = [[False] * k for _ in range(m + 1)]
        suffix[m][0] = True
        for i in range(m - 1, -1, -1):
            c = coeff[i]
            nxt = suffix[i + 1]
            cur = suffix[i]
            for r in range(k):
                for d in range(10):
                    if nxt[(r - d * c) % k]:
                        cur[r] = True
                        break
        ans = []
        rem = 0
        for i, c in enumerate(coeff):
            lo = 1 if i == 0 else 0
            for d in range(9, lo - 1, -1):
                nr = (rem + d * c) % k
                if suffix[i + 1][(-nr) % k]:
                    ans.append(str(d))
                    rem = nr
                    break
        half = ''.join(ans)
        return half + (half[:-1][::-1] if n % 2 else half[::-1])

