class Solution:
    def makeStringGood(self, s: str) -> int:
        n=len(s)
        cnt=[0]*26
        for ch in s: cnt[ord(ch)-97]+=1
        m=max(cnt)
        INF=10**9
        ans=n
        # incoming flow counts, outgoing is flow to next letter
        for k in range(1,m+1):
            dp=[INF]*(n+1); dp[0]=0
            for c in cnt:
                nd=[INF]*(n+1)
                # For each target t, minimize dp[p]+|t+q-p-c|, then add q.
                for t in (0,k):
                    # evaluate min_p dp[p]+|A-p| for A=t+q-c
                    pre=[INF]*(n+1)
                    best=INF
                    for p in range(n+1):
                        best=min(best,dp[p]-p)
                        pre[p]=best
                    suf=[INF]*(n+1); best=INF
                    for p in range(n,-1,-1):
                        best=min(best,dp[p]+p)
                        suf[p]=best
                    for q in range(n+1):
                        a=t+q-c
                        if a<0: val=pre[0]+(-a)
                        elif a>n: val=suf[n]+(a-n)
                        else: val=min(pre[a]+a,suf[a]-a)
                        if val+q < nd[q]: nd[q]=val+q
                dp=nd
            ans=min(ans,dp[0])
        return ans

