class Solution:
    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        n=len(edges)+1
        g=[[] for _ in range(n)]
        for a,b,w in edges:
            g[a].append((b,w)); g[b].append((a,w))
        parent=[-1]*n
        pw=[0]*n
        order=[0]
        parent[0]=0
        for u in order:
            for v,w in g[u]:
                if v != parent[u]:
                    parent[v]=u; pw[v]=w; order.append(v)
        f0=[0]*n
        f1=[0]*n
        for u in reversed(order):
            base=0; gains=[]
            for v,w in g[u]:
                if parent[v]==u:
                    base += f0[v]
                    gains.append(w+f1[v]-f0[v])
            gains.sort(reverse=True)
            pos=[x for x in gains if x>0]
            f0[u]=base+sum(pos[:k])
            f1[u]=base+sum(pos[:max(0,k-1)])
        return f0[0]

