class Solution:
    def _occ(self, s, pat):
        if not pat:
            return []
        m = len(pat)
        pi = [0] * m
        j = 0
        for i in range(1, m):
            while j and pat[i] != pat[j]:
                j = pi[j-1]
            if pat[i] == pat[j]:
                j += 1
                pi[i] = j
        out = []
        j = 0
        for i, ch in enumerate(s):
            while j and ch != pat[j]:
                j = pi[j-1]
            if ch == pat[j]:
                j += 1
                if j == m:
                    out.append(i-m+1)
                    j = pi[j-1]
        return out

    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        i = p.index('*')
        j = p.index('*', i+1)
        A, B, C = p[:i], p[i+1:j], p[j+1:]
        if not A and not B:
            return 0 if not C else (len(C) if self._occ(s, C) else -1)
        oa = self._occ(s, A) if A else []
        ob = self._occ(s, B) if B else []
        oc = self._occ(s, C) if C else []
        import bisect
        ans = len(s) + 1
        if A:
            for a in oa:
                pos = a + len(A)
                if B:
                    k = bisect.bisect_left(ob, pos)
                    if k == len(ob):
                        continue
                    pos = ob[k] + len(B)
                if C:
                    k = bisect.bisect_left(oc, pos)
                    if k == len(oc):
                        continue
                    end = oc[k] + len(C)
                else:
                    end = pos
                ans = min(ans, end-a)
        else:
            for b in ob:
                pos = b + len(B)
                if C:
                    k = bisect.bisect_left(oc, pos)
                    if k == len(oc):
                        continue
                    end = oc[k] + len(C)
                else:
                    end = pos
                ans = min(ans, end-b)
        return -1 if ans == len(s)+1 else ans

