from collections import deque

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    n = next(it); m = next(it)
    graph = [[] for _ in range(n)]
    for _ in range(m):
        x = next(it)-1; y = next(it)-1; z = next(it)
        graph[x].append((y,z)); graph[y].append((x,z))
    vals = [-1]*n
    ans = [0]*n
    for root in range(n):
        if vals[root] != -1:
            continue
        vals[root] = 0
        q = deque([root])
        comp = []
        while q:
            u = q.popleft()
            comp.append(u)
            for v,z in graph[u]:
                w = vals[u] ^ z
                if vals[v] == -1:
                    vals[v] = w
                    q.append(v)
                elif vals[v] != w:
                    print(-1)
                    return
        shift = 0
        for b in range(31):
            ones = sum((vals[u] >> b) & 1 for u in comp)
            zeros = len(comp)-ones
            if zeros < ones:
                shift |= 1 << b
        for u in comp:
            ans[u] = vals[u] ^ shift
    print(*ans)

