def solve(n,a,b):
    if n<=18:
        s=sum((c=='1')<<i for i,c in enumerate(a)); goal=sum((c=='1')<<i for i,c in enumerate(b))
        q=deque([s]); d={s:0}
        while q:
            x=q.popleft()
            if x==goal:return d[x]
            for i in range(n):
                y=0
