import sys

def main():
    data=sys.stdin.buffer.read().split()
    K=int(data[0]); S=data[1]; T=data[2]
    n=len(S); m=len(T)
    if abs(n-m)>K:
        print('No'); return
    l=0
    while l<n and l<m and S[l]==T[l]: l+=1
    S=S[l:]; T=T[l:]; n-=l; m-=l
    while n and m and S[n-1]==T[m-1]: n-=1; m-=1
    S=S[:n]; T=T[:m]
    if abs(n-m)>K:
        print('No'); return
    inf=K+1
    prev=[inf]*(m+1)
    for j in range(min(m,K)+1): prev[j]=j
    cur=[inf]*(m+1)
    for i in range(1,n+1):
        lo=max(0,i-K); hi=min(m,i+K)
        plo=max(0,i-1-K); phi=min(m,i-1+K)
        for j in range(lo,hi+1):
            if j==0:
                cur[j]=i
                continue
            v=inf
            if plo<=j<=phi: v=min(v,prev[j]+1)
            if j-1>=lo: v=min(v,cur[j-1]+1)
            if plo<=j-1<=phi: v=min(v,prev[j-1]+(S[i-1]!=T[j-1]))
            cur[j]=min(v,inf)
        prev,cur=cur,prev
    print('Yes' if prev[m]<=K else 'No')

