from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)

        # Generate the DFS postorder iteratively, preserving child order.
        order = []
        stack = [(0, 0)]
        while stack:
            x, done = stack.pop()
            if done:
                order.append(x)
            else:
                stack.append((x, 1))
                for y in reversed(children[x]):
                    stack.append((y, 0))

        pos = [0] * n
        size = [1] * n
        for k, x in enumerate(order):
            pos[x] = k
            if parent[x] != -1:
                size[parent[x]] += size[x]

        text = ''.join(s[x] for x in order)

        # Manacher radii for odd- and even-length palindromes.
        odd = [0] * n
        left, right = 0, -1
        for i in range(n):
            radius = 1 if i > right else min(odd[left + right - i], right - i + 1)
            while i - radius >= 0 and i + radius < n and text[i - radius] == text[i + radius]:
                radius += 1
            odd[i] = radius
            if i + radius - 1 > right:
                left, right = i - radius + 1, i + radius - 1

        even = [0] * n
        left, right = 0, -1
        for i in range(n):
            radius = 0 if i > right else min(even[left + right - i + 1], right - i + 1)
            while i - radius - 1 >= 0 and i + radius < n and text[i - radius - 1] == text[i + radius]:
                radius += 1
            even[i] = radius
            if i + radius - 1 > right:
                left, right = i - radius, i + radius - 1

        answer = [False] * n
        for x in range(n):
            end = pos[x]
            start = end - size[x] + 1
            length = size[x]
            if length % 2:
                answer[x] = odd[(start + end) // 2] >= length // 2 + 1
            else:
                answer[x] = even[(start + end + 1) // 2] >= length // 2
        return answer

