from math import gcd

class Solution:
    def maxScore(self, nums: List[int]) -> int:
        def score(arr):
            if not arr:
                return 0
            g = 0
            l = 1
            for x in arr:
                g = gcd(g, x)
                l = l // gcd(l, x) * x
            return g * l

        ans = score(nums)
        for i in range(len(nums)):
            ans = max(ans, score(nums[:i] + nums[i + 1:]))
        return ans

