    def findMaximumScore(self, nums: List[int]) -> int:
        ans = 0
        prev = 0
        for i in range(1, len(nums)):
            if nums[i] > nums[prev]:
                ans += (i - prev) * nums[prev]
                prev = i
        ans += (len(nums) - 1 - prev) * nums[prev]
        return ans

