from typing import List

class Solution:
    def getLargestOutlier(self, nums: List[int]) -> int:
        freq = {}
        for x in nums:
            freq[x] = freq.get(x, 0) + 1

        total = sum(nums)
        for x in sorted(freq, reverse=True):
            rem = total - x
            if rem % 2 == 0:
                y = rem // 2
                if freq.get(y, 0) >= (2 if y == x else 1):
                    return x

        return 0

