import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        if n == m:
            return -1 if self._is_prime(n) else n

        digits = len(str(n))
        hi = 10 ** digits
        prime = [True] * hi
        prime[0] = False
        if hi > 1:
            prime[1] = False
        for p in range(2, int((hi - 1) ** 0.5) + 1):
            if prime[p]:
                prime[p * p:hi:p] = [False] * (((hi - 1 - p * p) // p) + 1)

        if prime[n] or prime[m]:
            return -1

        dist = {n: n}
        pq = [(n, n)]
        while pq:
            cost, x = heapq.heappop(pq)
            if cost != dist[x]:
                continue
            if x == m:
                return cost

            s = str(x)
            for i, ch in enumerate(s):
                d = ord(ch) - 48
                place = 10 ** (digits - 1 - i)
                for nd in (d - 1, d + 1):
                    if 0 <= nd <= 9 and not (i == 0 and nd == 0):
                        y = x + (nd - d) * place
                        if not prime[y]:
                            nc = cost + y
                            if nc < dist.get(y, float('inf')):
                                dist[y] = nc
                                heapq.heappush(pq, (nc, y))
        return -1

    @staticmethod
    def _is_prime(x: int) -> bool:
        if x < 2:
            return False
        for d in range(2, int(x ** 0.5) + 1):
            if x % d == 0:
                return False
        return True

